from fractions import Fraction

WITNESS = [
    {'r': 2, 'N': 1000000, 'C': Fraction(101, 100), 'S': Fraction(1009999, 1)},
    {'r': 3, 'N': 1000000, 'C': Fraction(63, 10),   'S': Fraction(6299999, 1)},
    {'r': 4, 'N': 1000000, 'C': Fraction(49, 5),    'S': Fraction(9799999, 1)},
]

EXPECTED_C = {2: Fraction(101, 100), 3: Fraction(63, 10), 4: Fraction(49, 5)}
SCOPE_N_MAX = 10 ** 6


def verify(witness):
    # Fail-closed scope guards: abort (nonzero exit), never warn-and-continue.
    if SCOPE_N_MAX > 10 ** 6:
        raise SystemExit(2)
    seen = set()
    for e in witness:
        r = e['r']
        if r not in EXPECTED_C:
            raise SystemExit(2)  # r outside certified scope {2,3,4}: universal claim uncertifiable
        if r in seen:
            raise SystemExit(2)  # duplicate scope entry
        seen.add(r)
        N = e['N']
        if N <= 0 or N > SCOPE_N_MAX:
            raise SystemExit(2)  # N out of certified scope
        C = e['C']
        S = e['S']
        if not isinstance(C, Fraction) or not isinstance(S, Fraction):
            raise SystemExit(2)  # only exact rational arithmetic permitted
        if C != EXPECTED_C[r]:
            raise SystemExit(2)  # constant for r deviates from certified record
        if S < 0:
            raise SystemExit(2)  # negative square-sum record
        # Exact rational bound check, no tolerance: S_r <= C_r * N.
        if S > C * N:
            raise SystemExit(2)
    if seen != set(EXPECTED_C):
        raise SystemExit(2)  # missing scope entries
    return True


if not verify(WITNESS):
    raise SystemExit(2)
# Normal termination: exit 0 == PASS (all finite-scope bounds hold exactly).
